// server.js -- PC-hosted Node.js server.
// Runs the simulated audio generation on the PC and transmits 
// 48-byte binary UDP packets directly to the ESP32-S3 at 60 Hz.

const http = require('http');
const fs = require('fs');
const path = require('path');
const dgram = require('dgram');

// --- Configuration ---
let ESP32_IP = '192.168.1.123'; // Replace with your ESP32's IP or update via the UI
const UDP_PORT = 49152;
const HTTP_PORT = 3000;

// Shared audio metrics generated by PC simulation
const audioState = {
  bands: new Float32Array(8),
  level: 0.0,
  bass: 0.0,
  mid: 0.0,
  treb: 0.0
};

// --- UDP Audio Streamer ---
const udpSocket = dgram.createSocket('udp4');
const t0 = Date.now();

// 60 Hz update loop (~16.6 ms)
setInterval(() => {
  const t = (Date.now() - t0) / 1000.0;

  // Replicate the simulated audio generator from the original preview
  for (let b = 0; b < 8; b++) {
    audioState.bands[b] = 0.5 + 0.5 * Math.sin(t * (1.3 + b * 0.4) + b);
  }
  audioState.bass  = (audioState.bands[0] + audioState.bands[1]) / 2.0;
  audioState.mid   = (audioState.bands[2] + audioState.bands[3] + audioState.bands[4]) / 3.0;
  audioState.treb  = (audioState.bands[5] + audioState.bands[6] + audioState.bands[7]) / 3.0;
  audioState.level = audioState.bands.reduce((acc, v) => acc + v, 0) / 8.0;

  // Allocate 48-byte buffer matching ESP32 AudioPayload:
  // 12 little-endian IEEE 754 floats (8 bands + level + bass + mid + treb)
  const buf = Buffer.alloc(48);
  for (let i = 0; i < 8; i++) {
    buf.writeFloatLE(audioState.bands[i], i * 4);
  }
  buf.writeFloatLE(audioState.level, 32);
  buf.writeFloatLE(audioState.bass,  36);
  buf.writeFloatLE(audioState.mid,   40);
  buf.writeFloatLE(audioState.treb,  44);

  udpSocket.send(buf, 0, 48, UDP_PORT, ESP32_IP, (err) => {
    // Ignore transient unreachable/offline network errors
  });
}, 16);

// --- HTTP Web Server ---
const server = http.createServer((req, res) => {
  if (req.method === 'GET' && req.url === '/api/audio') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    return res.end(JSON.stringify({
      bands: Array.from(audioState.bands),
      level: audioState.level,
      bass: audioState.bass,
      mid: audioState.mid,
      treb: audioState.treb
    }));
  }

  if (req.method === 'POST' && req.url === '/api/config') {
    let body = '';
    req.on('data', chunk => { body += chunk; });
    req.on('end', () => {
      try {
        const data = JSON.parse(body);
        if (data.ip) {
          ESP32_IP = data.ip;
          console.log(`Updated ESP32 target IP to: ${ESP32_IP}`);
        }
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ ok: true, ip: ESP32_IP }));
      } catch (e) {
        res.writeHead(400);
        res.end(JSON.stringify({ error: 'invalid json' }));
      }
    });
    return;
  }

  // Serve static files from /public
  let filePath = path.join(__dirname, 'public', req.url === '/' ? 'index.html' : req.url);
  const ext = path.extname(filePath);
  const mimeTypes = {
    '.html': 'text/html',
    '.js': 'application/javascript',
    '.css': 'text/css',
    '.json': 'application/json'
  };

  fs.readFile(filePath, (err, content) => {
    if (err) {
      res.writeHead(404, { 'Content-Type': 'text/plain' });
      res.end('File not found');
    } else {
      res.writeHead(200, { 'Content-Type': mimeTypes[ext] || 'application/octet-stream' });
      res.end(content);
    }
  });
});

server.listen(HTTP_PORT, () => {
  console.log(`Web server listening at http://localhost:${HTTP_PORT}`);
  console.log(`Streaming simulated UDP audio to ${ESP32_IP}:${UDP_PORT}`);
});